const [open, setOpen] = useState(false);

<DropdownMenu
  aria-label="Matter actions"
  open={open}
  onOpenChange={setOpen}
  searchPlaceholder="Search actions"
  sections={[{
    id: 'actions',
    heading: 'Actions',
    items: [
      { id: 'rename', label: 'Rename', onSelect: () => { handleRename(); setOpen(false); } },
      { id: 'delete', label: 'Delete', onSelect: () => { handleDelete(); setOpen(false); } },
    ],
  }]}
>
  <Button onClick={() => setOpen((current) => !current)}>Actions</Button>
</DropdownMenu>

const [open, setOpen] = useState(false);

<DropdownMenu
  aria-label="Row actions"
  open={open}
  onOpenChange={setOpen}
  showSearch={false}
  sections={[{ id: 'actions', items: [{ id: 'archive', label: 'Archive', onSelect: () => setOpen(false) }] }]}
>
  <IconButton aria-label="Row actions" appearance="subtle" onClick={() => setOpen((current) => !current)}>
    <MoreVertIcon size="sm" decorative />
  </IconButton>
</DropdownMenu>
